-- J4c-1 — VERIFICAÇÃO (somente leitura; só nomes e contagens). Esperado: 10 policies; visitante sem nada; 8 funções seguras; trava de colunas ligada.
select 'policies nas 4 tabelas (esperado 10)' as item, (select count(*) from pg_policies where schemaname = 'public' and tablename in ('joiners', 'pre_cadastros', 'grupos_envio', 'push_subscriptions'))::text as valor
union all select 'policies para visitante/PUBLIC (esperado 0)', (select count(*) from pg_policies where schemaname = 'public' and tablename in ('joiners', 'pre_cadastros', 'grupos_envio', 'push_subscriptions') and ('anon' = any(roles) or 'public' = any(roles)))::text
union all select 'visitante com algum privilégio nas 4 tabelas (esperado false)',
       (select coalesce(bool_or(has_table_privilege('anon', x.nome, 'SELECT') or has_table_privilege('anon', x.nome, 'INSERT') or has_table_privilege('anon', x.nome, 'UPDATE') or has_table_privilege('anon', x.nome, 'DELETE') or has_any_column_privilege('anon', x.nome, 'SELECT') or has_any_column_privilege('anon', x.nome, 'UPDATE')), false)::text
          from (values ('public.joiners'), ('public.pre_cadastros'), ('public.grupos_envio'), ('public.push_subscriptions')) x(nome))
union all select 'funções seguras presentes (esperado 8)', (select count(*) from pg_proc p where p.pronamespace = 'public'::regnamespace and p.proname in ('solicitar_cadastro', 'resolver_recrutador', 'meus_recrutados', 'joiners_online', 'debitar_cashback', 'grupo_por_codigo', 'registrar_push', 'trg_joiners_protege_colunas') and p.prosecdef and p.proconfig = array['search_path=""'])::text
union all select 'trava de colunas da joiners ligada (esperado true)', exists (select 1 from pg_trigger where tgrelid = 'public.joiners'::regclass and tgname = 'trg_joiners_protege_colunas' and tgenabled = 'O')::text
union all select 'impressão antes | agora (joiners)', coalesce((select detalhe from emergencia.c0b_estado_anterior where etapa = 'J4c-1' and objeto = 'impressão joiners'), 'sem registro') || ' | ' || (select 'linhas=' || count(*) || ' md5=' || md5(coalesce(string_agg(id::text || coalesce(cog, '') || coalesce(email, ''), ',' order by id), '')) from public.joiners)
union all select 'estado registrado (linhas J4c-1, esperado >= 8)', (select count(*) from emergencia.c0b_estado_anterior where etapa = 'J4c-1')::text;
